import{C as r,o as l,c as n,a2 as s,E as d,j as t,a as u,t as p,p as b}from"./chunks/framework.D21_4UK8.js";const m={class:"rock-copy-email-wrapper inline"},P=JSON.parse('{"title":"概要 - Main St Audio Labs","description":"","frontmatter":{"layout":"doc","sidebar":false,"aside":false,"title":"概要 - Main St Audio Labs"},"headers":[],"relativePath":"ja/about.md","filePath":"ja/about.md"}'),h={name:"ja/about.md"},S=Object.assign(h,{setup(c){const e=b("メールアドレスをコピー");function i(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),e.value="コピーしました！",setTimeout(function(){e.value="メールアドレスをコピー"},2e3)}return(f,a)=>{const o=r("NewsletterSubscribe");return l(),n("div",null,[a[1]||(a[1]=s('<h1 id="main-st-audio-labs-について" tabindex="-1">Main St Audio Labs について <a class="header-anchor" href="#main-st-audio-labs-について" aria-label="Permalink to &quot;Main St Audio Labs について&quot;">​</a></h1><p>Main St Audio Labs は、ヴィンテージ・ロックンロールへの情熱、アナログモデリング技術、そしてソフトウェアエンジニアリングが交差する場所から生まれた個人開発プロジェクトです。</p><hr><h2 id="開発の背景とストーリー" tabindex="-1">開発の背景とストーリー <a class="header-anchor" href="#開発の背景とストーリー" aria-label="Permalink to &quot;開発の背景とストーリー&quot;">​</a></h2><p>Main St Audio Labs は、1960年代後半から1970年代初頭の生々しくダイナミックでタッチセンシティブなギタートーンに魅了されたギタリスト兼インディペンデント・オーディオデベロッパー、<strong>Emiliano Tegli</strong> によって設立されました。</p><p>ラボの名前は、ローリング・ストーンズの名盤『<em>Exile on Main St.</em>（メイン・ストリートのならず者）』の伝説的な地下スタジオ・セッションに由来しています。真空管が限界までドライブされ、ロックの歴史を決定づけた立体的で温かみのあるトーンへのオマージュです。</p><hr><h2 id="なぜ-main-st-audio-labs-なのか" tabindex="-1">なぜ Main St Audio Labs なのか？ <a class="header-anchor" href="#なぜ-main-st-audio-labs-なのか" aria-label="Permalink to &quot;なぜ Main St Audio Labs なのか？&quot;">​</a></h2><p>現代のオーディオプラグインは非常に高機能になりましたが、時に「音楽を作ること」そのものの妨げになってしまうことがあります。無限のパラメーター、複雑なルーティング、膨大なプリセットの海、そしてCPUを過剰に消費する重厚なUIに悩まされることも少なくありません。</p><p>私たちは異なるアプローチを信じています：<strong>「シンプルであることのマニフェスト」</strong>。</p><h3 id="📻-1-名盤のサウンドを忠実に再現-mix-ready" tabindex="-1">📻 1. 名盤のサウンドを忠実に再現（Mix-Ready） <a class="header-anchor" href="#📻-1-名盤のサウンドを忠実に再現-mix-ready" aria-label="Permalink to &quot;📻 1. 名盤のサウンドを忠実に再現（Mix-Ready）&quot;">​</a></h3><p>未処理の生々しいエミュレーションをそのまま提供し、ユーザーに過度なポストEQの負担を強いることはありません。各プラグインは、数々のクラシックアルバムや伝説的なライブ音源で聴かれるギター、シンセ、ダイナミクスレスポンスを綿密に分析・キャリブレーションして設計されており、DAWのミックスへ即座に馴染みます。</p><h3 id="⚡-2-徹底的な軽量設計-超低cpu負荷" tabindex="-1">⚡ 2. 徹底的な軽量設計＆超低CPU負荷 <a class="header-anchor" href="#⚡-2-徹底的な軽量設計-超低cpu負荷" aria-label="Permalink to &quot;⚡ 2. 徹底的な軽量設計＆超低CPU負荷&quot;">​</a></h3><p>PCの計算リソースは、重いグラフィック処理や非効率なDSPループではなく、あなたの音楽制作そのものに注がれるべきです。当ラボのすべてのツールは高度に最適化されたオーディオエンジンと無駄のないC++ DSPコードで構築されており、多数のトラックにインサートしてもストレスなく動作します。</p><hr><h2 id="私たちのミッション" tabindex="-1">私たちのミッション <a class="header-anchor" href="#私たちのミッション" aria-label="Permalink to &quot;私たちのミッション&quot;">​</a></h2><p>生々しく響き、オーガニックな弾き心地を持ち、プレイヤーのインスピレーションを決して妨げないバーチャル・ブティックオーディオツールを作ること。</p><p>ユーザー登録の壁や不要な常駐ソフトはありません。プラグインを立ち上げ、ノブを回せば、すぐに演奏を始められます。</p><hr><h2 id="🤝-友人・コラボレーターへの感謝" tabindex="-1">🤝 友人・コラボレーターへの感謝 <a class="header-anchor" href="#🤝-友人・コラボレーターへの感謝" aria-label="Permalink to &quot;🤝 友人・コラボレーターへの感謝&quot;">​</a></h2><p>Main St Audio Labs の研究開発は、情熱的なミュージシャンやトーンチェイサーの仲間たちのサポートによって支えられています：</p><ul><li><strong>Claudio Crespino</strong> — 数々のオーディオプロジェクトにおける貴重なテスト、フィードバック、継続的なサポートに心から感謝します。</li></ul>',22)),d(o),a[2]||(a[2]=t("hr",null,null,-1)),a[3]||(a[3]=t("h2",{id:"お問い合わせ-フィードバック",tabindex:"-1"},[u("お問い合わせ＆フィードバック "),t("a",{class:"header-anchor",href:"#お問い合わせ-フィードバック","aria-label":'Permalink to "お問い合わせ＆フィードバック"'},"​")],-1)),a[4]||(a[4]=t("p",null,"皆さまからのご意見・ご感想をいつでもお待ちしております。改善の提案、プラグインを使用して作成した音源、またはカスタムキャビネットのリクエストなどがございましたら、お気軽に下記までご連絡ください：",-1)),t("div",m,[a[0]||(a[0]=t("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),t("button",{class:"rock-copy-btn",onClick:i},p(e.value),1)]),a[5]||(a[5]=t("p",{style:{"margin-top":"2rem","margin-bottom":"1rem"}},"当ラボの独立した研究開発を支援し、プラグインの無料提供をサポートしていただける場合は、クレジットカード、PayPal、または仮想通貨でのご支援を受け付けております：",-1)),a[6]||(a[6]=t("div",null,[t("a",{href:"/ja/support",class:"rock-btn rock-btn-primary",style:{display:"inline-block","text-align":"center"}},"ラボの開発を支援する（Ko-fi / 仮想通貨） ☕")],-1))])}}});export{P as __pageData,S as default};
